import _vars from "../_vars.js";
import Cookies from "js-cookie";

if (!Cookies.get('cookie-block')) {
  _vars.cookieBlock.classList.add('cookie-block--visible');
  _vars.cookieBlockBtn.addEventListener('click', (e) => {
    Cookies.set('cookie-block', 'true', { expires: 31 })
    _vars.cookieBlock.classList.remove('cookie-block--visible');
  })
}
